juce::String ju(const std::string& s){return juce::String::fromUTF8(s.c_str());}
// Test-only index of the real GUI controls. Rebuild on form generation or
// dynamic-array structure change; weak component pointers preserve lifetimes.
// Every report still enters the actual widget and native gesture owner.
struct LookupIndex {
 juce::Component::SafePointer<juce::Component> root,form;
 std::uint64_t generation{};std::size_t referenceChecks{};
 std::map<std::string,juce::Component::SafePointer<juce::Component>> nodes;
};
std::map<juce::Component*,LookupIndex> lookupIndexes;
juce::Component* rawFind(juce::Component& p,const std::string& id){const auto target=ju(id);const auto visit=[&](const auto& self,juce::Component& c)->juce::Component*{if(c.getComponentID()==target)return &c;for(int i=0;i<c.getNumChildComponents();++i)if(auto* child=self(self,*c.getChildComponent(i)))return child;return nullptr;};return visit(visit,p);}
void invalidateLookup(juce::Component& p){lookupIndexes.erase(&p);}
juce::Component* find(juce::Component& p,const std::string& id){
 auto& index=lookupIndexes[&p];auto* form=dynamic_cast<desktop::TypedManualForm*>(index.form.getComponent());
 if(index.root.getComponent()!=&p||!form||form->formGeneration()!=index.generation){
  index=LookupIndex{};index.root=&p;
  const auto collect=[&](const auto& self,juce::Component& c)->void {const auto name=c.getComponentID().toStdString();if(!name.empty())index.nodes.emplace(name,&c);if(auto* typed=dynamic_cast<desktop::TypedManualForm*>(&c)){index.form=typed;index.generation=typed->formGeneration();}for(int n=0;n<c.getNumChildComponents();++n)self(self,*c.getChildComponent(n));};collect(collect,p);
 }
 const auto found=index.nodes.find(id);auto* result=found==index.nodes.end()?nullptr:found->second.getComponent();if(index.referenceChecks++<8)check(result==rawFind(p,id),"Indexed GUI lookup differs from actual component tree");return result;
}
template<class T>T& control(juce::Component& v,const std::string& id){auto* p=dynamic_cast<T*>(find(v,id));check(p!=nullptr,"CONTROL "+id);return *p;}
