 if(const auto* constant=schema.find("const")){check(*constant==value,"Fixture changed source/prior-choice constant");if(const auto* marked=schema.find("source_constant");marked&&*marked==V(true)&&schema.find("input_role")&&*schema.find("input_role")==V("source_binding")){check(control<juce::Label>(view,"typed-label-"+path).getText().startsWith("Printed / protocol binding: "),"Source binding not visibly labeled");check(!find(view,"typed-field-"+path),"Printed source binding became editable");}return;}
