 const auto& definition=H::definition(view.exactSourceKey());const auto atoms=json::parse(definition.sourceAtomsJson());const auto& atom=atoms.array().at(ordinal-1);
 const auto text=control<juce::TextEditor>(view,"typed-instructions").getText();
 check(text.contains(ju("Written note: "+f(atom,"note_spelling").string()+".")),"Written source note missing before contact");
 for(const auto& item:std::vector<std::pair<const char*,const char*>>{{"harmony","Active source chord: "},{"harmonic_role","Source chord role: "},{"color","Printed color: "},{"source_pitch_pool","Pitch pool: "}}){
  const auto* value=atom.find(item.first);if(value&&!value->null())check(text.contains(ju(std::string(item.second)+value->string())),"Source contact fact missing before traversal");
 }
 if(const auto* role=atom.find("harmonic_role");role&&*role==V("R"))check(text.contains("R is the harmonic root, not a rest"));
 if(const auto* pool=atom.find("source_pitch_pool");pool&&!pool->null())check(text.contains("not a backing chord"));
