 if(!cue.finger)check(text.contains("finger not specified"),"Source-null finger coerced in renderer");
 if(!cue.pick)check(text.contains("pick not specified"),"Source-null pick coerced in renderer");
 check(f(view.learnerView(),"source_clock").null(),"Manual source acquired a clock");safeText(view);
