void sourcePositive(View& view,const std::string& action){submit(view,action,sourcePayload(view,action));}
void sourceProjection(View& view){
 select(view,"contact");const auto cue=view.contactTask()->sourceAtomCue();
 const auto text=control<juce::TextEditor>(view,"typed-instructions").getText();
 check(!cue.atoms.empty(),"Empty Source atom projection");
 if(cue.simultaneous)check(text.contains("members are not serial attacks"),"Atomic group became a serial exercise");
 for(const auto& atom:cue.atoms){
  check(text.contains(ju("Source atom "+std::to_string(atom.sourceOrdinal)+": "+atom.stringLabel)),"Atomic member omitted");
  check(text.contains(ju(atom.kind)),"Source atom kind omitted");
  check(text.contains(ju(atom.physicalFret?"physical fret "+std::to_string(*atom.physicalFret):"physical fret unspecified")),"Physical fret coerced");
  if(atom.soundingFret&&atom.soundingFret!=atom.physicalFret)check(text.contains(ju("sounding target fret "+std::to_string(*atom.soundingFret))),"Sounding target lost");
  if(atom.referenceFret)check(text.contains(ju("printed reference/ceiling fret "+std::to_string(*atom.referenceFret))),"Reference fret lost");
  if(!atom.spelling.empty())check(text.contains(ju("written note "+atom.spelling)),"Written spelling lost");
  if(atom.audible==false)check(text.contains("NONAUDIBLE reference/preparation"),"Reference became audible");
  if(!atom.finger)check(text.contains("finger unspecified"),"Null finger coerced");
  if(!atom.pick)check(text.contains(atom.picked==false?"no new pick":"pick direction unspecified"),"Pick absence coerced");
  if(atom.onset)check(text.contains(ju("Source-relative authored onset cue "+std::to_string(atom.onset->numerator())+"/"+std::to_string(atom.onset->denominator()))),"Source-relative onset omitted");
  if(atom.handSlotDuration)check(text.contains(ju("Authored hand slot "+std::to_string(atom.handSlotDuration->numerator())+"/"+std::to_string(atom.handSlotDuration->denominator()))),"Hand slot omitted");
 }
 const auto& first=cue.atoms.front();
 check(text.contains(ju(first.midi?", MIDI pitch "+std::to_string(*first.midi):", MIDI pitch not specified")),"Renderer legacy MIDI fallback");
 check(text.contains(ju(first.physicalFret?", physical fret "+std::to_string(*first.physicalFret):", physical fret not specified")),"Renderer legacy fret fallback");
 check(f(view.learnerView(),"source_clock").null(),"Source atom acquired a clock");
 safeText(view);
}
